//! The Haas library (data/machines/haas.toml, generated by tools/machines/haas.py): every record
//! real and fully cited, the published numbers where the record says they are, and sample jobs
//! simulated end to end on the VF-2 (posted by forge-post's `haas` dialect), the UMC-750 and the
//! ST-20: kinematics, limits, collisions and removal.
use forge_machine::collide::{self, Role, Verdict};
use forge_machine::def::{CiteStatus, Kind, MachineDef, Prim};
use forge_machine::gcode::Control;
use forge_machine::library::{builtin_files, builtin_named};
use forge_machine::removal;
use forge_machine::sim::{self, Cut, Setup, SimTool};
use forge_post::{Coolant, CycleKind, Dialect, Program, Rec};

fn haas(name: &str) -> MachineDef {
    builtin_named(name).unwrap_or_else(|| panic!("no built-in {name}"))
}

fn joint<'a>(m: &'a MachineDef, n: &str) -> &'a forge_machine::def::Joint {
    m.joint(n).unwrap()
}

#[test]
fn the_haas_library_is_real_and_cited() {
    let ms: Vec<MachineDef> = builtin_files()
        .into_iter()
        .filter(|(_, f)| f == "builtin/haas.toml")
        .map(|(m, _)| m)
        .collect();
    let names: Vec<&str> = ms.iter().map(|m| m.name.as_str()).collect();
    for want in [
        "haas-vf-2",
        "haas-vf-2ss",
        "haas-vf-3",
        "haas-vf-4",
        "haas-mini-mill",
        "haas-tm-1",
        "haas-tm-2",
        "haas-dt-1",
        "haas-dm-1",
        "haas-umc-750",
        "haas-st-10",
        "haas-st-20",
        "haas-st-30",
        "haas-st-10y",
        "haas-st-20y",
        "haas-st-30y",
        "haas-ds-30y",
        "haas-vf-1",
        "haas-vf-2yt",
        "haas-vf-3yt",
        "haas-vf-5-40",
        "haas-vf-6-40",
        "haas-super-mini-mill",
        "haas-tm-0",
        "haas-dt-2",
        "haas-dm-2",
        "haas-umc-400",
        "haas-umc-500",
        "haas-umc-750ss",
        "haas-umc-1000",
        "haas-st-15",
        "haas-st-25",
        "haas-st-35",
        "haas-st-40",
        "haas-tl-1",
        "haas-tl-2",
    ] {
        assert!(names.contains(&want), "{want} missing from {names:?}");
    }
    for m in &ms {
        assert!(m.real, "{}", m.name);
        // validate_cites ran on parse; here: every published or conflict cite has a source and a
        // date, every estimate or unknown a basis
        for c in &m.cites {
            match c.status {
                CiteStatus::Published | CiteStatus::Conflict => {
                    assert!(
                        c.source.starts_with("https://") && c.taken.len() == 10,
                        "{} {c:?}",
                        m.name
                    )
                }
                CiteStatus::Estimate | CiteStatus::Unknown => {
                    assert!(!c.basis.is_empty(), "{} {c:?}", m.name)
                }
            }
        }
        for p in m.cite_paths() {
            assert!(m.cites.iter().any(|c| c.path == p), "{}: {p}", m.name);
        }
    }
}

/// The records hold the published numbers (machinetoolindex.com restating haascnc.com, read
/// 2026-11-23): inches and ipm converted at 25.4.
#[test]
fn published_numbers_land_where_the_cites_say() {
    let m = haas("haas-vf-2");
    assert_eq!(m.kind, Kind::Vmc3);
    assert_eq!(joint(&m, "X").range, [-762.0, 0.0]); // 30 in
    assert_eq!(joint(&m, "Y").range, [-406.0, 0.0]); // 16 in
    assert_eq!(joint(&m, "Z").range, [-508.0, 0.0]); // 20 in
    for n in ["X", "Y", "Z"] {
        assert_eq!(joint(&m, n).rapid, 25400.0); // 1000 ipm
        assert_eq!(joint(&m, n).max_feed, 16500.0); // 650 ipm restated as 16.5 m/min
    }
    let s = &m.spindles[0];
    assert_eq!(s.rpm[1], 8100.0);
    assert_eq!(s.nose[2], 610.0); // spindle nose to table, max: 24 in
    assert_eq!(s.nose[2] + joint(&m, "Z").range[0], 102.0); // ... min: 4 in
    let c = m.changer.as_ref().unwrap();
    assert_eq!((c.pockets, c.change_s, c.max_tool_kg), (20, 4.5, 5.4));
    // the power curve never exceeds the published 22.4 kW peak nor 122 N·m
    for w in s.power.windows(2) {
        assert!(w[1][1] <= 22.4);
        if w[1][0] > 0.0 {
            assert!(w[1][1] * 1000.0 / (w[1][0] * std::f64::consts::TAU / 60.0) <= 122.0 + 1e-9);
        }
    }

    let ss = haas("haas-vf-2ss");
    assert_eq!(joint(&ss, "X").rapid, 35600.0); // 1400 ipm restated as 35.6 m/min
    assert_eq!(ss.spindles[0].rpm[1], 12000.0);

    let u = haas("haas-umc-750");
    assert_eq!(u.kind, Kind::TableTable);
    assert_eq!(joint(&u, "B").range, [-35.0, 120.0]);
    assert_eq!(joint(&u, "B").rapid, 3000.0); // 50 deg/s
    assert_eq!(joint(&u, "C").rapid, 3000.0);
    assert_eq!(joint(&u, "X").rapid, 22900.0); // 900 ipm restated as 22.9 m/min
    assert_eq!(joint(&u, "Y").range, [-508.0, 0.0]);
    // the conflicting Haas UK rapid is recorded, not silently dropped
    assert!(
        u.cites
            .iter()
            .any(|c| c.path == "joint.X.rapid" && c.status == CiteStatus::Conflict)
    );

    let t = haas("haas-st-20");
    assert_eq!(t.kind, Kind::Lathe);
    let x = joint(&t, "X");
    assert!(x.diameter);
    assert_eq!(x.range[1] - x.range[0], 213.0); // 8.4 in of X
    assert_eq!(x.range[1], 165.0); // max turning diameter 13 in (330 mm)
    assert_eq!(joint(&t, "Z").range, [0.0, 572.0]); // 22.5 in
    assert_eq!(t.spindles[0].rpm[1], 4000.0);
    assert_eq!(t.turrets[0].stations, 12);

    let y = haas("haas-st-20y");
    assert_eq!(y.kind, Kind::MillTurn);
    assert_eq!(joint(&y, "Y").range, [-51.0, 51.0]); // ± 2 in
    let d = haas("haas-ds-30y");
    assert_eq!(d.kind, Kind::MillTurn);
    assert!(d.mount("sub").is_some());
}

fn mill_tool(t: u32, len: f64, r: f64) -> SimTool {
    SimTool {
        t,
        name: format!("t{t}"),
        tip: [0.0, 0.0, -len],
        body: vec![(r, 0.0, 25.0), (r + 3.0, 25.0, 60.0), (20.0, 60.0, len)],
        cut: Cut::Mill { r, corner: 0.0 },
    }
}

/// A VF-2 job posted by forge-post's `haas` dialect: face, a slot, a circle, a peck-drilled hole
/// pattern. Simulated on the real travel: no violations, no collisions, the slot depth in the
/// removal map. Then the same machine with a rapid through the vise jaw: a hit.
#[test]
fn vf2_posted_job_end_to_end() {
    let m = haas("haas-vf-2");
    let d = Dialect::get("haas").unwrap();
    let prog = Program {
        number: 1001,
        title: "vf2 sample".into(),
        recs: vec![
            Rec::Comment("face, slot, circle, holes".into()),
            Rec::Wcs(0),
            Rec::ToolChange {
                t: 1,
                h: 1,
                name: "flat-12".into(),
            },
            Rec::Spindle {
                rpm: 6000.0,
                cw: true,
            },
            Rec::Coolant(Coolant::Flood),
            Rec::Rapid([-60.0, -20.0, 40.0]),
            Rec::Rapid([-60.0, -20.0, 25.0]),
            Rec::Line([-60.0, -20.0, 19.0], 600.0),
            Rec::Line([60.0, -20.0, 19.0], 1500.0),
            Rec::Rapid([60.0, -20.0, 30.0]),
            Rec::Rapid([-40.0, 10.0, 30.0]),
            Rec::Line([-40.0, 10.0, 15.0], 300.0),
            Rec::Line([40.0, 10.0, 15.0], 1200.0),
            Rec::Arc {
                to: [40.0, 30.0, 15.0],
                c: [40.0, 20.0],
                cw: false,
                f: 1000.0,
            },
            Rec::Rapid([40.0, 30.0, 40.0]),
            // a Haas M06 sends Z to machine zero by itself (HFO Mill Programming manual, M06);
            // forge-machine's changer moves no joint (FORMAT-GAPS #8), so the post's G28 Z0 says it
            Rec::Home,
            Rec::ToolChange {
                t: 2,
                h: 2,
                name: "drill-8".into(),
            },
            Rec::Spindle {
                rpm: 2500.0,
                cw: true,
            },
            Rec::Rapid([-30.0, -10.0, 40.0]),
            Rec::Cycle {
                kind: CycleKind::Peck,
                holes: vec![[-30.0, -10.0], [0.0, -10.0], [30.0, -10.0]],
                z: 2.0,
                r: 23.0,
                clear: 40.0,
                q: 4.0,
                dwell: 0.0,
                f: 250.0,
            },
            Rec::Coolant(Coolant::Off),
            Rec::SpindleStop,
            Rec::Home,
        ],
    };
    let q = forge_post::quantize(&prog, &d).unwrap();
    let text = forge_post::print(&q, &d).unwrap();
    assert!(text.contains("G187 P2") && text.contains("G83"), "{text}");

    let c = Control::for_dialect(&m, "haas", 1).unwrap();
    assert_eq!(c.letters, vec!['Y', 'X', 'Z']);
    let mut s = Setup::new(&m, c).unwrap();
    // part frame = the table top centre: the spindle is over it at X -381, Y -203 (mid-travel);
    // Z word 0 at the table top: q_Z = word - 610 + H
    s.wcs = vec![(54, vec![-203.0, -381.0, -610.0])];
    s.tools = vec![mill_tool(1, 110.0, 6.0), mill_tool(2, 140.0, 4.0)];
    s.h = vec![(1, 110.0), (2, 140.0)];
    let tl = sim::simulate(&text, &s).unwrap();
    assert!(tl.violations.is_empty(), "{:?}", tl.violations);

    // a 140 x 80 x 20 block on the table, held by a jaw at y = -50 .. -40 (20 high)
    let stock_min = [-70.0, -40.0, 0.0];
    let stock_max = [70.0, 40.0, 20.0];
    let jaw = collide::part_body(
        &s,
        "jaw",
        &[Prim::Box {
            min: [-80.0, -55.0, 0.0],
            max: [80.0, -40.0, 30.0],
        }],
        Role::Fixture,
    );
    let r = collide::check(&s, &tl, std::slice::from_ref(&jaw));
    assert!(r.contacts.is_empty(), "{:?}", r.contacts);
    let rm = removal::mill(&s, &tl, stock_min, stock_max, 1.0).unwrap();
    assert!(rm.rapid_cuts.is_empty(), "{:?}", rm.rapid_cuts);
    // the slot along y = 10 is 15 high, the faced band at y = -20 is 19 high, the drilled holes
    // reach z = 2 under the 4 mm drill
    let at = |x: f64, y: f64| {
        let i = ((x - stock_min[0]) / 1.0).round() as usize;
        let j = ((y - stock_min[1]) / 1.0).round() as usize;
        rm.map.at(i, j)
    };
    assert_eq!(at(0.0, 10.0), 15.0);
    assert_eq!(at(0.0, -20.0), 19.0);
    assert_eq!(at(0.0, -10.0), 2.0);
    assert_eq!(at(-65.0, 35.0), 20.0);

    // a rapid at z = 25 straight through the jaw (top at 30): the holder side of the tool hits
    let crash = "G90 G21\nT1 M06\nG54\nG43 H1\nG0 X0 Y-80. Z60.\nZ25.\nY0\n";
    let tl = sim::simulate(crash, &s).unwrap();
    let r = collide::check(&s, &tl, std::slice::from_ref(&jaw));
    assert!(
        r.contacts
            .iter()
            .any(|c| matches!(c.verdict, Verdict::Hit { .. }) && (c.a == "jaw" || c.b == "jaw")),
        "{:?}",
        r.contacts
    );
    // and past the travel: X beyond the table end is an overtravel
    let tl = sim::simulate("G90 G21\nT1 M06\nG54\nG43 H1\nG0 X420. Y0 Z60.\n", &s).unwrap();
    assert!(!tl.violations.is_empty());
}

/// The UMC-750: a 3+2 job (B and C positioned, then 3-axis moves) on the platter; the trunnion
/// and the head stay clear; tilting past the published +120 is an overtravel.
#[test]
fn umc750_tilted_job_end_to_end() {
    let m = haas("haas-umc-750");
    let c = Control::for_dialect(&m, "haas", 1).unwrap();
    assert_eq!(c.letters, vec!['X', 'Y', 'Z', 'B', 'C']);
    let mut s = Setup::new(&m, c).unwrap();
    // the spindle over the platter centre at mid-travel: X -381, Y -254; Z word 0 at the platter top
    s.wcs = vec![(54, vec![-381.0, -254.0, -610.0, 0.0, 0.0])];
    s.tools = vec![mill_tool(1, 120.0, 5.0)];
    s.h = vec![(1, 120.0)];
    s.start_tool = Some(1);
    let prog = "G90 G21\nG54\nG43 H1\nG0 X0 Y0 Z200. B0 C0\n\
                G1 X-40. Y0 Z45. F2000.\nX40.\nG0 Z200.\n\
                G0 B30. C90.\nG1 X-30. Y0 Z120. F1500.\nX30.\nG0 Z250.\n\
                G0 B0 C0\n";
    let tl = sim::simulate(prog, &s).unwrap();
    assert!(tl.violations.is_empty(), "{:?}", tl.violations);
    let stock = collide::part_body(
        &s,
        "stock",
        &[Prim::Box {
            min: [-50.0, -50.0, 0.0],
            max: [50.0, 50.0, 40.0],
        }],
        Role::Stock,
    );
    let r = collide::check(&s, &tl, std::slice::from_ref(&stock));
    assert!(r.contacts.is_empty(), "{:?}", r.contacts);
    // 30 deg of B at 3000 deg/min (50 deg/s, published) is at least 0.6 s
    let b = tl
        .segments
        .iter()
        .find(|g| g.q0[3] == 0.0 && g.q1[3] == 30.0)
        .unwrap();
    assert!(b.t_min >= 0.6 - 1e-12, "{}", b.t_min);
    let tl = sim::simulate("G90 G21\nG54\nG43 H1\nG0 X0 Y0 Z250. B125.\n", &s).unwrap();
    assert!(!tl.violations.is_empty());
}

/// The ST-20: face and turn a bar in the chuck (removal: the turned diameter), the published
/// 4000 rpm as the clamp ceiling; then a rapid into the chuck: a hit.
#[test]
fn st20_turned_job_end_to_end() {
    let m = haas("haas-st-20");
    let d = "[dialect]\nname = \"t\"\ndecimals = 3\nfeed_decimals = 3\ndwell = \"G04 P{ms}\"\n";
    let c = Control::for_machine(&m, d, 1).unwrap();
    assert_eq!(c.letters, vec!['Z', 'X']);
    let mut s = Setup::new(&m, c).unwrap();
    // the part's face at z = 100; the tool's tip 40 mm in from the reference point (geometry
    // offset X 40), so the X word is the tip's diameter
    s.wcs = vec![(54, vec![100.0, 0.0])];
    let rn = 0.8;
    s.tools = vec![SimTool {
        t: 1,
        name: "OD".into(),
        tip: [-40.0, 0.0, 0.0],
        body: vec![(6.0, 0.0, 40.0)],
        cut: Cut::Nose { rn, centre: [rn, rn] },
    }];
    s.geo = vec![(1, vec![0.0, 40.0])];
    let prog = "G18 G21\nT0101\nG50 S4000\nG96 S200 M03\nG0 X64. Z0\nG95 G1 X-2. F0.15\nG0 Z2.\nX50.\nG1 Z-60. F0.2\nX64.\nG0 Z5.\n";
    let tl = sim::simulate(prog, &s).unwrap();
    assert!(tl.violations.is_empty(), "{:?}", tl.violations);
    let r = collide::check(&s, &tl, &[]);
    assert!(r.contacts.is_empty(), "{:?}", r.contacts);
    let rm = removal::turn(&s, &tl, 31.0, 0.0, 101.0, 0.1).unwrap();
    assert!(rm.rapid_cuts.is_empty(), "{:?}", rm.rapid_cuts);
    for i in 0..rm.map.r.len() {
        let z = rm.map.z(i);
        if z > 100.0 + 1e-9 {
            assert_eq!(rm.map.r[i], 0.0, "z {z}");
        } else if z > 40.0 + 2.0 * rn + 1e-9 && z < 100.0 - 1e-9 {
            assert!((rm.map.r[i] - 25.0).abs() < 1e-9, "z {z}: {}", rm.map.r[i]);
        } else if z < 40.0 - 1e-9 {
            assert_eq!(rm.map.r[i], 31.0, "z {z}");
        }
    }
    // over the 4000 rpm ceiling: refused
    let tl = sim::simulate("G18 G21\nT0101\nG97 S4500 M03\n", &s).unwrap();
    assert!(!tl.violations.is_empty());
    // a rapid to Z -105 (5 mm off the chuck's face) at X 120: the tool runs into the chuck
    let tl = sim::simulate("G18 G21\nT0101\nG0 X120. Z5.\nZ-105.\n", &s).unwrap();
    let r = collide::check(&s, &tl, &[]);
    assert!(
        r.contacts
            .iter()
            .any(|c| matches!(c.verdict, Verdict::Hit { .. }) && (c.a == "chuck" || c.b == "chuck")),
        "{:?}",
        r.contacts
    );
}
